theorem ProbabilityTheory.Kernel.extracted_1.{u_4, u_3, u_2} {S : Type u_2} {T : Type u_3} {U : Type u_4}
  [inst : MeasurableSpace S] [inst_1 : MeasurableSpace T] [inst_2 : MeasurableSpace U] [inst_3 : Countable S]
  [inst_4 : MeasurableSingletonClass S] [inst_5 : Countable T] [inst_6 : MeasurableSingletonClass T] {η : Kernel T U}
  {ν : Measure S} [inst_7 : IsProbabilityMeasure ν] {μ : Measure T} [inst_8 : IsZeroOrProbabilityMeasure μ]
  [inst_9 : FiniteSupport μ] [inst_10 : FiniteSupport ν] :
  ∫ (x : S), ∫ (y : T), Hm[η (x, y).2] ∂μ ∂ν = ∫ (x : T), Hm[η x] ∂μ := sorry

theorem ProbabilityTheory.Kernel.extracted_1.{u_4, u_3, u_2} {S : Type u_2} {T : Type u_3} {U : Type u_4}
  [inst : MeasurableSpace S] [inst_1 : MeasurableSpace T] [inst_2 : MeasurableSpace U] [inst_3 : Countable S]
  [inst_4 : MeasurableSingletonClass S] [inst_5 : Countable T] [inst_6 : MeasurableSingletonClass T] {κ : Kernel T S}
  {η : Kernel T U} [inst_7 : IsMarkovKernel κ] {μ : Measure T} [inst_8 : IsZeroOrProbabilityMeasure μ]
  [inst_9 : FiniteSupport μ] (hκ : κ.AEFiniteKernelSupport μ) :
  ∫ (a : T), ∫ (b : S), Hm[η (a, b).1] ∂κ a ∂μ = ∫ (x : T), Hm[η x] ∂μ := sorry

