  {η : Kernel T U} [inst_7 : IsMarkovKernel κ] {μ : Measure T} [inst_8 : IsZeroOrProbabilityMeasure μ]
  [inst_9 : FiniteSupport μ] (hκ : κ.AEFiniteKernelSupport μ) : Integrable (fun x => Hm[η x.1]) (μ ⊗ₘ κ) := sorry

theorem ProbabilityTheory.Kernel.extracted_1.{u_4, u_3, u_2} {S : Type u_2} {T : Type u_3} {U : Type u_4}
  [inst : MeasurableSpace S] [inst_1 : MeasurableSpace T] [inst_2 : MeasurableSpace U]
  [inst_3 : MeasurableSingletonClass S] [inst_4 : MeasurableSingletonClass T] [inst_5 : MeasurableSingletonClass U]
  {μ : Measure T} [inst_6 : IsFiniteMeasure μ] {κ : Kernel T S} [inst_7 : IsZeroOrMarkovKernel κ] {η : Kernel (T × S) U}
  [inst_8 : IsMarkovKernel η] [inst_9 : FiniteSupport μ] (hκ : κ.FiniteKernelSupport) (hη : η.FiniteKernelSupport)
  (hκ' : IsMarkovKernel κ) :
  let A := μ.support;
  (∀ (F : T → ℝ), ∫ (t : T), F t ∂μ = ∑ t ∈ A, μ.real {t} * F t) →
    Hk[κ ⊗ₖ η , μ] = Hk[κ , μ] + ∫ (x : T), (fun t => Hk[η.comap (Prod.mk t) ⋯ , κ t]) x ∂μ := sorry

theorem ProbabilityTheory.Kernel.extracted_1.{u_4, u_3, u_2} {S : Type u_2} {T : Type u_3} {U : Type u_4}
  [inst : MeasurableSpace S] [inst_1 : MeasurableSpace T] [inst_2 : MeasurableSpace U]
  [inst_3 : MeasurableSingletonClass S] [inst_4 : MeasurableSingletonClass T] [inst_5 : MeasurableSingletonClass U]
  {μ : Measure T} [inst_6 : IsFiniteMeasure μ] {κ : Kernel T S} [inst_7 : IsZeroOrMarkovKernel κ] {η : Kernel (T × S) U}
  [inst_8 : IsMarkovKernel η] [inst_9 : FiniteSupport μ] (hκ : κ.FiniteKernelSupport) (hη : η.FiniteKernelSupport)
  (hκ' : IsMarkovKernel κ) :
  let A := μ.support;
  (∀ (F : T → ℝ), ∫ (t : T), F t ∂μ = ∑ t ∈ A, μ.real {t} * F t) →
    ∑ t ∈ A, μ.real {t} * Hm[(κ ⊗ₖ η) t] =
      ∑ x ∈ A, (μ.real {x} * Hm[κ x] + μ.real {x} * ∫ (x_1 : S), Hm[(η.comap (Prod.mk x) ⋯) x_1] ∂κ x) := sorry

theorem ProbabilityTheory.Kernel.extracted_1.{u_4, u_3, u_2} {S : Type u_2} {T : Type u_3} {U : Type u_4}
  [inst : MeasurableSpace S] [inst_1 : MeasurableSpace T] [inst_2 : MeasurableSpace U]
  [inst_3 : MeasurableSingletonClass U] (κ : Kernel T S) [inst_4 : IsMarkovKernel κ] {f : T × S → U}
  (hf : ∀ (t : T), Function.Injective fun x => f (t, x)) (hmes : Measurable f) (t : T) :
  (κ ⊗ₖ deterministic f hmes).snd t = (κ.map fun x => f (t, x)) t := sorry
